  sessionId: string | null
  /** True while verifying credentials or restoring session */
  isLoading: boolean
  error: string | null
}

interface AuthActions {
  login(username: string, password: string): Promise<void>
  logout(): Promise<void>
  restoreSession(): Promise<void>
  clearError(): void
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/** Return the master AES-GCM key, creating and persisting it on first call. */
async function getOrCreateMasterKey(): Promise<CryptoKey> {
  const stored = localStorage.getItem(LS_ENC_KEY)
  if (stored) {
    return importKey(stored)
  }
  const key = await generateEncryptionKey()
  localStorage.setItem(LS_ENC_KEY, await exportKey(key))
  return key
}

// ── Store ─────────────────────────────────────────────────────────────────────
export const useAuthStore = create<AuthState & AuthActions>((set, get) => ({
  currentUser: null,
  sessionId: null,
  isLoading: false,
  error: null,

  clearError: () => set({ error: null }),

  // ── login ──────────────────────────────────────────────────────────────────
  async login(username, password) {
    set({ isLoading: true, error: null })
    try {
      // 1. Look up user (case-insensitive username)
      const user = await db.users
        .where('username')
        .equals(username.toLowerCase().trim())
        .first()

      // Use same error message for "not found" and "wrong password"
      // to avoid leaking which field is wrong
      if (!user ?? !user?.isActive) {
        set({ isLoading: false, error: 'Invalid username or password' })
        return
      }

      // 2. Verify PBKDF2 hash
      const valid = await verifyPassword(password, user.passwordHash, user.passwordSalt)
      if (!valid) {
        set({ isLoading: false, error: 'Invalid username or password' })
        return
      }

      // 3. Create session record in IndexedDB
      const sessionId = generateId()
      const now = Date.now()
      const expiresAt = now + SESSION_DURATION_MS

      await db.sessions.add({
        id: sessionId,
        userId: user.id,
        token: sessionId,
        createdAt: now,
        expiresAt,
      })

      // 4. Encrypt session token → LocalStorage
      const masterKey = await getOrCreateMasterKey()
      const tokenPayload: SessionToken = { sessionId, userId: user.id, expiresAt }
      const encryptedToken = await encrypt(JSON.stringify(tokenPayload), masterKey)
      localStorage.setItem(LS_SESSION, encryptedToken)

      // 5. Append-only audit log
      await writeAuditLog({
        eventType: 'user.login',
        actorId: user.id,
        actorName: user.displayName,
        entityType: 'User',
        entityId: user.id,
        description: `${user.displayName} signed in`,
      })

      set({ currentUser: user, sessionId, isLoading: false, error: null })
    } catch {
      set({ isLoading: false, error: 'Login failed. Please try again.' })
    }
  },

  // ── logout ─────────────────────────────────────────────────────────────────
  async logout() {
    const { currentUser, sessionId } = get()

    try {
      if (currentUser && sessionId) {
        await writeAuditLog({
          eventType: 'user.logout',
          actorId: currentUser.id,
          actorName: currentUser.displayName,
          entityType: 'User',
          entityId: currentUser.id,
          description: `${currentUser.displayName} signed out`,
        })
        await db.sessions.delete(sessionId)
      }
    } catch {
      // Best-effort — still clear the local session even if DB write fails
    }

    localStorage.removeItem(LS_SESSION)
    set({ currentUser: null, sessionId: null, isLoading: false, error: null })
  },

  // ── restoreSession ─────────────────────────────────────────────────────────
  async restoreSession() {
    set({ isLoading: true })
    try {
      const storedKey = localStorage.getItem(LS_ENC_KEY)
      const storedSession = localStorage.getItem(LS_SESSION)

      if (!storedKey || !storedSession) {
        set({ isLoading: false })
        return
      }

      const masterKey = await importKey(storedKey)
      const tokenJson = await decrypt(storedSession, masterKey)
      const token = JSON.parse(tokenJson) as SessionToken

      // Check expiry
      if (Date.now() > token.expiresAt) {
        localStorage.removeItem(LS_SESSION)
        set({ isLoading: false })
        return
      }

      // Verify session still exists in IndexedDB
      const session = await db.sessions.get(token.sessionId)
      if (!session) {
        localStorage.removeItem(LS_SESSION)
        set({ isLoading: false })
        return
      }

      // Load and verify user
      const user = await db.users.get(token.userId)
      if (!user?.isActive) {
        localStorage.removeItem(LS_SESSION)
        set({ isLoading: false })
        return
      }

      set({ currentUser: user, sessionId: token.sessionId, isLoading: false })
    } catch {
      // Corrupted or tampered session data — force re-login
      localStorage.removeItem(LS_SESSION)
      set({ isLoading: false })
    }
  },
}))

// ── Default admin seeding ─────────────────────────────────────────────────────

/**
 * On first launch (no users in DB), create the default Administrator account.
 * The default password is temporary — user is prompted to change it on first login.
 *
 * Default credentials:
 *   username : admin
 *   password : Admin@1234!
 */
export async function seedDefaultAdmin(): Promise<void> {
  const count = await db.users.count()
  if (count > 0) return

  const { hash, salt } = await hashPassword('Admin@1234!')
  const now = Date.now()

  await db.users.add({
    id: generateId(),
    username: 'admin',
    displayName: 'Administrator',
    email: '',
    passwordHash: hash,
    passwordSalt: salt,
    role: Role.Administrator,
    isActive: true,
    isTemporaryPassword: true,
    createdAt: now,
    updatedAt: now,
    createdBy: 'system',
  })
}
"}

