{"file_path": "/Users/muhammed/projects/eaglepoint/TASK-114/repo/src/App.tsx", "content": "import { useEffect } from 'react'
import { Toaster } from 'sonner'
import { Loader2, LogOut, Shield } from 'lucide-react'
import { useAuthStore, seedDefaultAdmin } from '@/store/authStore'
import { LoginPage } from '@/pages/LoginPage'

export default function App() {
  const currentUser = useAuthStore((s) => s.currentUser)
  const isLoading = useAuthStore((s) => s.isLoading)

  // On mount: seed default admin (no-op if users exist), then restore persisted session
  useEffect(() => {
    const initialize = async () => {
      await seedDefaultAdmin()
      await useAuthStore.getState().restoreSession()
    }
    void initialize()
  }, [])

  // ── Full-screen loading (session restore in progress) ─────────────────────
  if (isLoading && !currentUser) {
    return (
      <>
        <Toaster position="top-right" richColors />
        <div className="min-h-screen bg-surface-950 flex items-center justify-center">
          <div className="flex flex-col items-center gap-3">
            <Loader2 className="w-8 h-8 text-primary-500 animate-spin" />
            <p className="text-surface-500 text-sm">Loading…</p>
          </div>
        </div>
      </>
    )
  }

  // ── Not authenticated ─────────────────────────────────────────────────────
  if (!currentUser) {
    return (
      <>
        <Toaster position="top-right" richColors />
        <LoginPage />
      </>
    )
  }

  // ── Authenticated — app shell placeholder (Phase 2) ───────────────────────
  return (
    <>
      <Toaster position="top-right" richColors />
      <div className="min-h-screen bg-surface-950 flex items-center justify-center">
        <div className="text-center">
          <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-primary-600 mb-4">
            <Shield className="w-7 h-7 text-white" />
          </div>
          <h1 className="text-2xl font-bold text-surface-50 mb-1">
            Welcome, {currentUser.displayName}
          </h1>
          <p className="text-surface-500 text-sm mb-6">{currentUser.role}</p>
          <button
            onClick={() => { void useAuthStore.getState().logout() }}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-surface-800
              hover:bg-surface-700 text-surface-300 text-sm transition-colors border border-surface-700"
          >
            <LogOut className="w-4 h-4" />
            Sign out
          </button>
          <p className="text-surface-700 text-xs mt-8">App shell coming in Phase 2</p>
        </div>
      </div>
    </>
  )
}
"}

