interface FieldWrapperProps {
  label?: string
  htmlFor?: string
  error?: string
  hint?: string
  children: React.ReactNode
}

export function FieldWrapper({ label, htmlFor, error, hint, children }: FieldWrapperProps) {
  return (
    <div className="flex flex-col gap-1.5">
      {label && (
        <label htmlFor={htmlFor} className="text-sm font-medium text-surface-400">
          {label}
        </label>
      )}
      {children}
      {error && <p className="text-xs text-red-400">{error}</p>}
      {!error && hint && <p className="text-xs text-surface-600">{hint}</p>}
    </div>
  )
}

// ── Base input class helper ────────────────────────────────────────────────────

export function inputBase(hasError = false, extra = '') {
  return [
    'w-full bg-surface-800 border rounded-xl text-surface-100 placeholder:text-surface-600 text-sm',
    'outline-none transition-colors',
    'focus:border-primary-500 focus:ring-1 focus:ring-primary-500/50',
    hasError ? 'border-red-500/70' : 'border-surface-700',
    'disabled:opacity-50 disabled:cursor-not-allowed',
    extra,
  ].join(' ')
}

// ── Input ──────────────────────────────────────────────────────────────────────

interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string
  error?: string
  hint?: string
  leftIcon?: React.ReactNode
  rightIcon?: React.ReactNode
}

export function Input({
  label,
  error,
  hint,
  leftIcon,
  rightIcon,
  id,
  className = '',
  ...props
}: InputProps) {
  const hasError = Boolean(error)
  return (
    <FieldWrapper label={label} htmlFor={id} error={error} hint={hint}>
      <div className="relative">
        {leftIcon && (
          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-surface-600 pointer-events-none">
            {leftIcon}
          </span>
        )}
        <input
          id={id}
          aria-invalid={hasError}
          className={[inputBase(hasError, leftIcon ? 'pl-10' : 'px-3'), 'py-2.5', className].join(
            ' ',
          )}
          {...props}
        />
        {rightIcon && (
