{"file_path": "/Users/muhammed/projects/eaglepoint/TASK-114/repo/src/services/biddingEngine.ts", "content": "/**
 * BiddingEngine — deterministic, cross-tab-safe bidding with:
 *  - Minimum increment enforcement
 *  - Proxy bid auto-resolution (timestamp + amount ordering)
 *  - Anti-sniping: extend end time by 2 min once when bid placed in final 30s
 *  - Idempotency keys to prevent duplicate bids from cross-tab races
 *  - BroadcastChannel for live updates to other open tabs
 *
 * Design decisions per CLAUDE.md #3, #4, #10.
 */

import { db } from '@/db'
import { generateId } from '@/crypto'
import { writeAuditLog } from '@/utils/audit'
import { reserveForAuction } from './walletService'
import type { Bid, ProxyBid } from '@/types'

// ── BroadcastChannel ──────────────────────────────────────────────────────────

export type BidEvent =
  | { type: 'BID_PLACED'; auctionId: string; bid: Bid; newPrice: number }
  | { type: 'AUCTION_EXTENDED'; auctionId: string; newEndTime: number }
  | { type: 'AUCTION_CLOSED'; auctionId: string }

let _channel: BroadcastChannel | null = null

function getBroadcastChannel(): BroadcastChannel {
  if (!_channel) _channel = new BroadcastChannel('meridian_bids')
  return _channel
}

export function subscribeToBidEvents(handler: (event: BidEvent) => void): () => void {
  const ch = getBroadcastChannel()
  const listener = (e: MessageEvent<BidEvent>) => {
    handler(e.data)
  }
  ch.addEventListener('message', listener)
  return () => {
    ch.removeEventListener('message', listener)
  }
}

function broadcast(event: BidEvent): void {
  getBroadcastChannel().postMessage(event)
}

// ── Anti-sniping constants ─────────────────────────────────────────────────────

const SNIPE_WINDOW_MS = 30_000 // 30 seconds
const SNIPE_EXTENSION_MS = 2 * 60_000 // 2 minutes

// ── Internal helpers ───────────────────────────────────────────────────────────

async function insertBid(
  auctionId: string,
  bidderId: string,
  amount: number,
  isProxyResolved: boolean,
  idempotencyKey: string,
): Promise<Bid> {
  const bid: Bid = {
    id: generateId(),
    auctionId,
    bidderId,
    amount,
    isProxyResolved,
    idempotencyKey,
    createdAt: Date.now(),
  }
  await db.bids.add(bid)
  return bid
}

/**
 * Run proxy resolution for `auctionId` after a new manual bid of `incomingAmount`
 * from `incomingBidderId`. Returns the final winning bid after proxies are resolved.
 */
async function resolveProxies(
  auctionId: string,
  incomingAmount: number,
  incomingBidderId: string,
  minimumIncrement: number,
): Promise<{ winningBidderId: string; winningAmount: number; bid: Bid | null }> {
  // Fetch all active proxy bids for other bidders, ordered by maxAmount desc, then createdAt asc
  const proxies = await db.proxyBids
    .where('[auctionId+bidderId]')
    .between([auctionId, Dexie.minKey], [auctionId, Dexie.maxKey])
    .filter((p) => p.isActive && p.bidderId !== incomingBidderId)
    .toArray()

  // Sort: highest maxAmount first; ties broken by earliest proxy bid
  proxies.sort((a, b) => b.maxAmount - a.maxAmount || a.createdAt - b.createdAt)

  const topProxy = proxies[0]

  // No competing proxy → incoming bid stands
  if (!topProxy || topProxy.maxAmount <= incomingAmount) {
    return { winningBidderId: incomingBidderId, winningAmount: incomingAmount, bid: null }
  }

  // Competing proxy can outbid — auto-raise to just enough to beat incoming bid
  const counterAmount = Math.min(
    topProxy.maxAmount,
    incomingAmount + minimumIncrement,
  )

  const counterBid = await insertBid(
    auctionId,
    topProxy.bidderId,
    counterAmount,
    true, // isProxyResolved
    generateId(),
  )

  return {
    winningBidderId: topProxy.bidderId,
    winningAmount: counterAmount,
    bid: counterBid,
  }
}

// ── placeBid ───────────────────────────────────────────────────────────────────

export interface PlaceBidResult {
  success: boolean
  bid?: Bid
  newPrice: number
  message: string
  extended?: boolean
}

export async function placeBid(
  auctionId: string,
  bidderId: string,
  bidderName: string,
  amount: number,
  idempotencyKey: string,
  depositAmount: number,
  previousDepositHeld: number,
): Promise<PlaceBidResult> {
  // ── Wrap everything in a Dexie rw transaction ────────────────────────────
  return db.transaction(
    'rw',
    db.auctions,
    db.bids,
    db.proxyBids,
    db.wallets,
    db.walletTransactions,
    db.auditLogs,
    async () => {
      const auction = await db.auctions.get(auctionId)
      if (!auction) return { success: false, newPrice: 0, message: 'Auction not found' }

      if (auction.status !== 'Active' && auction.status !== 'Extended') {
        return { success: false, newPrice: auction.currentPrice, message: 'Auction is not accepting bids' }
      }
      if (Date.now() > auction.endTime) {
        return { success: false, newPrice: auction.currentPrice, message: 'Auction has ended' }
      }
      if (amount < auction.currentPrice + auction.minimumIncrement) {
        return {
          success: false,
          newPrice: auction.currentPrice,
          message: `Minimum bid is ${auction.currentPrice + auction.minimumIncrement}`,
        }
      }

      // Idempotency check — ConstraintError on duplicate key means already placed
      const existing = await db.bids.where('idempotencyKey').equals(idempotencyKey).first()
      if (existing) {
        return { success: true, bid: existing, newPrice: auction.currentPrice, message: 'Already placed' }
      }

      // Insert the manual bid
      const bid = await insertBid(auctionId, bidderId, amount, false, idempotencyKey)

      // Proxy resolution
      const { winningBidderId, winningAmount, bid: proxyBid } = await resolveProxies(
        auctionId,
        amount,
        bidderId,
        auction.minimumIncrement,
      )

      const finalPrice = winningAmount
      const finalBid = proxyBid ?? bid

      // Anti-sniping — extend end time once by 2 min if bid in final 30s
      let extended = false
      let newEndTime = auction.endTime
      if (!auction.antiSnipingTriggered && auction.endTime - Date.now() <= SNIPE_WINDOW_MS) {
        newEndTime = auction.endTime + SNIPE_EXTENSION_MS
        extended = true
      }

      // Update auction price + optional extension
      await db.auctions.update(auctionId, {
        currentPrice: finalPrice,
        ...(extended ? { endTime: newEndTime, status: 'Extended', antiSnipingTriggered: true } : {}),
        updatedAt: Date.now(),
      })

      // Reserve deposit in wallet (replaces previous hold for this user on this auction)
      await reserveForAuction(bidderId, auctionId, depositAmount, previousDepositHeld)

      // Release previous winner's deposit hold if they were outbid by proxy
      if (winningBidderId !== bidderId && proxyBid) {
        // The proxy winner already has their own hold — no action needed here
      }

      await writeAuditLog({
        eventType: 'bid.placed',
        actorId: bidderId,
        actorName: bidderName,
        entityType: 'Auction',
        entityId: auctionId,
        description: `${bidderName} bid ${amount} on auction ${auctionId}`,
      })

      // Broadcast to other tabs
      broadcast({ type: 'BID_PLACED', auctionId, bid: finalBid, newPrice: finalPrice })
      if (extended) broadcast({ type: 'AUCTION_EXTENDED', auctionId, newEndTime })

      return {
        success: true,
        bid: finalBid,
        newPrice: finalPrice,
        message: winningBidderId === bidderId ? 'Bid placed!' : 'You were outbid by a proxy bid',
        extended,
      }
    },
  )
}

// ── setProxyBid ────────────────────────────────────────────────────────────────

export async function setProxyBid(
  auctionId: string,
  bidderId: string,
  bidderName: string,
  maxAmount: number,
  depositAmount: number,
  previousDepositHeld: number,
): Promise<{ success: boolean; message: string }> {
  const auction = await db.auctions.get(auctionId)
  if (!auction) return { success: false, message: 'Auction not found' }
  if (auction.status !== 'Active' && auction.status !== 'Extended') {
    return { success: false, message: 'Auction is not accepting bids' }
  }
  if (maxAmount <= auction.currentPrice) {
    return { success: false, message: 'Proxy max must exceed current price' }
  }

  await db.transaction('rw', db.proxyBids, db.wallets, db.walletTransactions, async () => {
    // Deactivate any existing proxy bid for this bidder on this auction
    const existing = await db.proxyBids
      .where('auctionId')
      .equals(auctionId)
      .filter((p) => p.bidderId === bidderId && p.isActive)
      .first()

    if (existing) {
      await db.proxyBids.update(existing.id, { isActive: false, updatedAt: Date.now() })
    }

    await db.proxyBids.add({
      id: generateId(),
      auctionId,
      bidderId,
      maxAmount,
      isActive: true,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    })

    await reserveForAuction(bidderId, auctionId, depositAmount, previousDepositHeld)
  })

  await writeAuditLog({
    eventType: 'bid.proxy_set',
    actorId: bidderId,
    actorName: bidderName,
    entityType: 'Auction',
    entityId: auctionId,
    description: `${bidderName} set proxy bid (max: ${maxAmount}) on auction ${auctionId}`,
  })

  // Immediately attempt a manual bid at the current minimum to trigger proxy engine
  const minBid = auction.currentPrice + auction.minimumIncrement
  if (maxAmount >= minBid) {
    await placeBid(
      auctionId,
      bidderId,
      bidderName,
      minBid,
      generateId(),
      depositAmount,
      depositAmount, // already reserved above
    )
  }

  return { success: true, message: 'Proxy bid set' }
}

// Need to import Dexie for minKey/maxKey
import Dexie from 'dexie'
"}

