{"file_path": "/Users/muhammed/projects/eaglepoint/TASK-114/repo/src/services/auctionLifecycle.ts", "content": "/**
 * AuctionLifecycle — auction close logic + polling timer.
 *
 * Design decisions:
 *  - No-bid → NoSale, notify seller, release all holds (CLAUDE.md #1)
 *  - Win → Awarded, deduct deposit from winner (CLAUDE.md #2)
 *  - Timer polls every 15 s; BroadcastChannel syncs across tabs
 */

import { db } from '@/db'
import { writeAuditLog } from '@/utils/audit'
import { generateId } from '@/crypto'
import { deductDeposit, releaseReservation } from './walletService'
import { broadcast } from './biddingEngineInternal'
import type { Auction } from '@/types'

// ── closeAuction ───────────────────────────────────────────────────────────────

export async function closeAuction(auction: Auction): Promise<void> {
  // Guard: only close auctions in a closeable state
  if (!['Active', 'Extended', 'Ended'].includes(auction.status)) return

  const bids = await db.bids
    .where('auctionId')
    .equals(auction.id)
    .sortBy('amount')

  // ── No bids → NoSale ───────────────────────────────────────────────────────
  if (bids.length === 0) {
    await db.auctions.update(auction.id, { status: 'NoSale', updatedAt: Date.now() })

    await writeAuditLog({
      eventType: 'auction.no_sale',
      actorId: 'system',
      actorName: 'System',
      entityType: 'Auction',
      entityId: auction.id,
      description: `Auction "${auction.title}" closed with no bids (No Sale)`,
    })

    // Notify seller
    await db.notifications.add({
      id: generateId(),
      userId: auction.createdBy,
      type: 'auction_no_sale',
      title: 'Auction Ended — No Sale',
      body: `Your auction "${auction.title}" received no bids and has been marked as No Sale.`,
      isRead: 0 as unknown as boolean,
      relatedEntityType: 'Auction',
      relatedEntityId: auction.id,
      createdAt: Date.now(),
    })

    broadcast({ type: 'AUCTION_CLOSED', auctionId: auction.id })
    return
  }

  // ── Determine winner (highest bid; ties broken by earliest createdAt) ───────
  const sorted = [...bids].sort((a, b) => b.amount - a.amount || a.createdAt - b.createdAt)
  const winningBid = sorted[0]!

  await db.transaction(
    'rw',
    db.auctions,
    db.bids,
    db.proxyBids,
    db.wallets,
    db.walletTransactions,
    db.notifications,
    db.auditLogs,
    async () => {
      // Mark auction as Awarded
      await db.auctions.update(auction.id, {
        status: 'Awarded',
        winnerId: winningBid.bidderId,
        winningBidId: winningBid.id,
        updatedAt: Date.now(),
      })

      // Deactivate all proxy bids for this auction
      const proxies = await db.proxyBids.where('auctionId').equals(auction.id).toArray()
      await Promise.all(
        proxies.map((p) => db.proxyBids.update(p.id, { isActive: false, updatedAt: Date.now() })),
      )

      // Deduct deposit from winner
      await deductDeposit(winningBid.bidderId, auction.id, auction.depositAmount)

      // Release reservation for all losing bidders
      const loserIds = [...new Set(bids.map((b) => b.bidderId))].filter(
        (id) => id !== winningBid.bidderId,
      )
      await Promise.all(
        loserIds.map((loserId) =>
          releaseReservation(loserId, auction.id, auction.depositAmount),
        ),
      )

      // Notify winner
      await db.notifications.add({
        id: generateId(),
        userId: winningBid.bidderId,
        type: 'auction_won',
        title: 'You Won the Auction!',
        body: `Congratulations! Your bid of ${winningBid.amount} won "${auction.title}". Deposit of ${auction.depositAmount} has been deducted.`,
        isRead: 0 as unknown as boolean,
        relatedEntityType: 'Auction',
        relatedEntityId: auction.id,
        createdAt: Date.now(),
      })

      // Notify losers
      await Promise.all(
        loserIds.map((loserId) =>
          db.notifications.add({
            id: generateId(),
            userId: loserId,
            type: 'auction_lost',
            title: 'Auction Ended',
            body: `The auction "${auction.title}" has ended. Your deposit hold has been released.`,
            isRead: 0 as unknown as boolean,
            relatedEntityType: 'Auction',
            relatedEntityId: auction.id,
            createdAt: Date.now(),
          }),
        ),
      )

      await writeAuditLog({
        eventType: 'auction.awarded',
        actorId: 'system',
        actorName: 'System',
        entityType: 'Auction',
        entityId: auction.id,
        description: `Auction "${auction.title}" awarded to bidder ${winningBid.bidderId} at ${winningBid.amount}`,
      })
    },
  )

  broadcast({ type: 'AUCTION_CLOSED', auctionId: auction.id })
}

// ── Timer ──────────────────────────────────────────────────────────────────────

let _timer: ReturnType<typeof setInterval> | null = null

/** Poll for ended auctions every 15 s and close them. Call once on app start. */
export function startAuctionLifecycleTimer(): () => void {
  const tick = async () => {
    const now = Date.now()
    const ended = await db.auctions
      .where('status')
      .anyOf('Active', 'Extended')
      .filter((a) => a.endTime <= now)
      .toArray()

    for (const auction of ended) {
      // Mark as Ended first (prevents double-processing across tabs)
      const updated = await db.transaction('rw', db.auctions, async () => {
        const fresh = await db.auctions.get(auction.id)
        if (!fresh || !['Active', 'Extended'].includes(fresh.status)) return false
        await db.auctions.update(auction.id, { status: 'Ended', updatedAt: Date.now() })
        return true
      })

      if (updated) {
        const fresh = await db.auctions.get(auction.id)
        if (fresh) await closeAuction(fresh)
      }
    }
  }

  // Run immediately then every 15 s
  void tick()
  _timer = setInterval(() => {
    void tick()
  }, 15_000)

  return () => {
    if (_timer !== null) {
      clearInterval(_timer)
      _timer = null
    }
  }
}
