              size="sm"
              onClick={() =>
                openTab({
                  id: `catalog-edit-${r.item.id}`,
                  title: `Edit: ${r.item.title}`,
                  path: `/catalog/${r.item.id}/edit`,
                })
              }
            >
              Edit
            </Button>
          )}
          {r.item.status === 'Draft' && canCreate && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => void handlePublish(r.item.id)}
            >
              Publish
            </Button>
          )}
          {r.item.status === 'Active' && canManage && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => void handleArchive(r.item.id)}
            >
              Archive
            </Button>
          )}
          {r.item.status === 'Archived' && canManage && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => void handleRestore(r.item.id)}
            >
              Restore
            </Button>
          )}
        </div>
      ),
    },
  ]

  return (
    <div className="p-6 space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-lg font-semibold text-surface-100">Catalog</h1>
          <p className="text-sm text-surface-500 mt-0.5">Manage catalog items</p>
        </div>
        {canCreate && (
          <Button
            variant="primary"
            size="sm"
            onClick={() =>
              openTab({ id: 'catalog-new', title: 'New Item', path: '/catalog/new' })
