          <EmptyState
            icon={Package}
            title="No items"
            description={
              statusFilter === 'All'
                ? 'Create your first catalog item.'
                : `No ${statusFilter} items.`
            }
          />
        ) : (
          <Table columns={columns} data={filtered} rowKey={(r) => r.item.id} isLoading={isLoading} />
        )}
      </Card>
    </div>
  )
}
"}

