    setIsLoading(true)
    const pubs = await db.publications.orderBy('updatedAt').reverse().toArray()
    setPublications(pubs)
    setIsLoading(false)
  }

  useEffect(() => {
    void load()
  }, [])

  if (!currentUser) return null

  const filtered =
    statusFilter === 'All' ? publications : publications.filter((p) => p.status === statusFilter)

