          {pub.status === 'InReview' && canReview && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                openTab({
                  id: `pub-review-${pub.id}`,
                  title: `Review: ${pub.title}`,
                  path: `/publishing/${pub.id}/review`,
                })
              }}
            >
              Review
            </Button>
