        {filtered.length === 0 && !isLoading ? (
          <EmptyState
            icon={FileText}
            title="No publications"
            description={statusFilter === 'All' ? 'Create your first publication.' : `No ${statusFilter} publications.`}
          />
        ) : (
          <Table
            columns={columns}
            data={filtered}
            rowKey={(pub) => pub.id}
            isLoading={isLoading}
          />
        )}
      </Card>
    </div>
  )
}
"}

