    status: 'Draft',
    moderationFlags,
    createdBy: actorId,
    createdAt: Date.now(),
    updatedAt: Date.now(),
  }
  await db.documents.add(doc)
  await writeAuditLog({
    eventType: 'document.created',
    actorId,
    actorName,
    entityType: 'Document',
    entityId: doc.id,
    description: `${actorName} created document "${doc.title}"`,
  })
  return doc
}

