        <CardHeader title="Body" />
        {errors.body && <p className="text-xs text-red-400 mb-2">{errors.body}</p>}
        <RichTextEditor
          value={body}
          onChange={(html) => {
            setBody(html)
            setDirty(true)
          }}
          disabled={!canEdit}
