          <p className="text-xs text-surface-400 truncate">{item.body}</p>
        </div>
      ),
    },
    {
      key: 'status',
      header: 'Status',
      width: 'w-24',
      cell: (item) => <Badge variant={STATUS_VARIANTS[item.status]}>{item.status}</Badge>,
