import { ForcePasswordChangePage } from '@/pages/ForcePasswordChangePage'
import { useAuthStore } from '@/store/authStore'
import { Role } from '@/types'

vi.mock('sonner', () => ({ toast: { error: vi.fn(), success: vi.fn() } }))

function makeTemporaryUser() {
  return {
    id: 'tmp-user-1',
    username: 'editor',
    displayName: 'Content Editor',
    email: 'editor@meridian.internal',
    passwordHash: 'hash',
    passwordSalt: 'salt',
    role: Role.ContentEditor,
    isActive: true,
    isTemporaryPassword: true,
    createdAt: 0,
    updatedAt: 0,
    createdBy: 'system',
  }
}

function renderPage() {
  return render(<ForcePasswordChangePage />)
}

describe('ForcePasswordChangePage — rendering', () => {
  beforeEach(() => {
    useAuthStore.setState({
      currentUser: makeTemporaryUser(),
      sessionId: 'test',
      isLoading: false,
      error: null,
    })
  })

  afterEach(() => {
    useAuthStore.setState({
      currentUser: {
        id: 'test-system-user',
        username: 'system',
        displayName: 'Test System',
        email: 'system@test',
        passwordHash: '',
        passwordSalt: '',
        role: Role.Administrator,
        isActive: true,
        isTemporaryPassword: false,
        createdAt: 0,
        updatedAt: 0,
        createdBy: 'system',
      },
      sessionId: 'test-session',
      isLoading: false,
      error: null,
    })
  })

  it('renders the heading and instruction text', () => {
    renderPage()
    expect(screen.getByText(/set a new password/i)).toBeInTheDocument()
    expect(screen.getByText(/temporary password/i)).toBeInTheDocument()
  })

  it('renders all three password fields', () => {
    renderPage()
    expect(screen.getByLabelText(/current password/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/new password/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/confirm new password/i)).toBeInTheDocument()
  })

  it('renders the submit button', () => {
    renderPage()
    expect(screen.getByRole('button', { name: /set new password/i })).toBeInTheDocument()
  })

  it('renders the sign-out link', () => {
    renderPage()
    expect(screen.getByRole('button', { name: /sign out/i })).toBeInTheDocument()
  })

  it('returns null when there is no current user', () => {
    useAuthStore.setState({ currentUser: null })
    const { container } = renderPage()
    expect(container.firstChild).toBeNull()
  })
})

describe('ForcePasswordChangePage — validation', () => {
  beforeEach(() => {
    useAuthStore.setState({ currentUser: makeTemporaryUser() })
  })

  it('requires current password', async () => {
    renderPage()
    fireEvent.click(screen.getByRole('button', { name: /set new password/i }))
    expect(await screen.findByText(/current password is required/i)).toBeInTheDocument()
  })

  it('requires new password to be at least 12 characters', async () => {
    renderPage()
    await userEvent.type(screen.getByLabelText(/current password/i), 'anything')
    await userEvent.type(screen.getByLabelText(/new password/i), 'tooshort')
    fireEvent.click(screen.getByRole('button', { name: /set new password/i }))
    expect(await screen.findByText(/at least 12 characters/i)).toBeInTheDocument()
  })

  it('rejects a new password identical to the current one', async () => {
    renderPage()
    await userEvent.type(screen.getByLabelText(/current password/i), 'SamePassword1!')
    await userEvent.type(screen.getByLabelText(/new password/i), 'SamePassword1!')
    fireEvent.click(screen.getByRole('button', { name: /set new password/i }))
    expect(await screen.findByText(/must differ from the current one/i)).toBeInTheDocument()
  })

  it('requires confirm to match new password', async () => {
    renderPage()
    await userEvent.type(screen.getByLabelText(/current password/i), 'OldPassword1!')
    await userEvent.type(screen.getByLabelText(/new password/i), 'NewPassword1!')
    await userEvent.type(screen.getByLabelText(/confirm new password/i), 'Mismatch!')
    fireEvent.click(screen.getByRole('button', { name: /set new password/i }))
    expect(await screen.findByText(/passwords do not match/i)).toBeInTheDocument()
  })
})
"}

