  inApp: boolean
  /** Whether the user wants email outbound messages */
  email: boolean
  /** Whether the user wants SMS outbound messages */
  sms: boolean
  updatedAt: number
}

// ── Read receipt ───────────────────────────────────────────────────────────────

export interface MessageReadReceipt {
  id: string
  notificationId: string
  userId: string
  readAt: number
}"}

