/**
 * AES-GCM-256 symmetric encryption using the Web Crypto API.
 *
 * Usage pattern for session tokens in LocalStorage:
 *   1. Call `generateEncryptionKey()` once on first app load.
 *   2. Persist the key with `exportKey()` → store in LocalStorage as "masterKey".
 *   3. Restore on subsequent loads with `importKey()`.
 *   4. Use `encrypt()` / `decrypt()` for any sensitive value.
 *
 * Wire format: base64( IV[12 bytes] || Ciphertext )
 *   - Random 12-byte IV is prepended to ciphertext so each call is unique.
 *   - AES-GCM authentication tag (16 bytes) is appended automatically by the API.
 */

const IV_LENGTH = 12 // bytes — standard for AES-GCM

// ── Internal helpers ─────────────────────────────────────────────────────────

function bufferToBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer)
  let binary = ''
  for (const byte of bytes) {
    binary += String.fromCharCode(byte)
  }
  return btoa(binary)
}

function base64ToUint8Array(base64: string): Uint8Array {
  const binary = atob(base64)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i)
  }
  return bytes
}

// ── Key management ────────────────────────────────────────────────────────────

/**
 * Generate a fresh AES-GCM-256 encryption key.
 * Call once per device/browser; persist via `exportKey`.
 */
export async function generateEncryptionKey(): Promise<CryptoKey> {
  return crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt'])
}

/**
 * Export a CryptoKey to a base64 string safe for LocalStorage.
 */
export async function exportKey(key: CryptoKey): Promise<string> {
  const raw = await crypto.subtle.exportKey('raw', key)
  return bufferToBase64(raw)
}

/**
 * Re-import a CryptoKey previously exported with `exportKey`.
 */
export async function importKey(base64: string): Promise<CryptoKey> {
  // Pass the Uint8Array directly — SubtleCrypto accepts ArrayBufferView,
  // avoiding ArrayBuffer realm-mismatch errors in some test environments.
  const raw = base64ToUint8Array(base64)
  return crypto.subtle.importKey('raw', raw, { name: 'AES-GCM', length: 256 }, true, [
    'encrypt',
    'decrypt',
  ])
}

// ── Encrypt / Decrypt ─────────────────────────────────────────────────────────

/**
 * Encrypt a UTF-8 plaintext string.
 * Returns a base64-encoded string containing IV + ciphertext + GCM auth tag.
 */
export async function encrypt(plaintext: string, key: CryptoKey): Promise<string> {
  const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH))
  const encoded = new TextEncoder().encode(plaintext)
  const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, encoded)

  // Combine IV + ciphertext into a single buffer
  const combined = new Uint8Array(IV_LENGTH + ciphertext.byteLength)
  combined.set(iv, 0)
  combined.set(new Uint8Array(ciphertext), IV_LENGTH)

  return bufferToBase64(combined.buffer)
}

/**
 * Decrypt a value previously encrypted with `encrypt`.
 * Throws a DOMException if the key is wrong or the ciphertext is tampered.
 */
export async function decrypt(base64Ciphertext: string, key: CryptoKey): Promise<string> {
  const combined = base64ToUint8Array(base64Ciphertext)
  const iv = combined.slice(0, IV_LENGTH)
  const ciphertext = combined.slice(IV_LENGTH)

  const decrypted = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext)
  return new TextDecoder().decode(decrypted)
}

/**
 * WalletService — all wallet mutations go through here.
 *
 * Design decisions (per CLAUDE.md #2):
 *  - Deduct deposit ONLY on auction win.
 *  - During active bidding, hold a "reserved" amount (no deduction yet).
 *  - All mutations are wrapped in Dexie transactions for atomicity.
 */

import { db } from '@/db'
import { generateId } from '@/crypto'
import type { WalletTransactionType } from '@/types'

// ── Internal helper ────────────────────────────────────────────────────────────

async function recordTransaction(
  walletId: string,
  userId: string,
  type: WalletTransactionType,
  amount: number,
  description: string,
  createdBy: string,
  relatedAuctionId?: string,
): Promise<void> {
  await db.walletTransactions.add({
    id: generateId(),
    walletId,
    userId,
    type,
    amount,
    description,
    createdBy,
    relatedAuctionId,
    createdAt: Date.now(),
  })
}

// ── Public API ─────────────────────────────────────────────────────────────────

/** Ensure a wallet record exists for the user; create one (zero balance) if not. */
export async function ensureWallet(userId: string): Promise<void> {
  const existing = await db.wallets.where('userId').equals(userId).first()
  if (!existing) {
    await db.wallets.add({
      id: generateId(),
      userId,
      balance: 0,
      reservedAmount: 0,
      updatedAt: Date.now(),
    })
  }
}

/** Credit (add funds) to a user's wallet. Admin-initiated manual top-up. */
export async function creditWallet(
  userId: string,
  amount: number,
  description: string,
  actorId: string,
  relatedAuctionId?: string,
): Promise<void> {
  if (amount <= 0) throw new Error('Credit amount must be positive')
  await ensureWallet(userId)

  await db.transaction('rw', db.wallets, db.walletTransactions, async () => {
    const wallet = await db.wallets.where('userId').equals(userId).first()
    if (!wallet) throw new Error('Wallet not found')
    await db.wallets.update(wallet.id, {
      balance: wallet.balance + amount,
      updatedAt: Date.now(),
    })
    await recordTransaction(
      wallet.id,
      userId,
      'Credit',
      amount,
      description,
      actorId,
      relatedAuctionId,
    )
  })
}

/** Debit (remove funds) from a user's wallet. Throws if insufficient available balance. */
export async function debitWallet(
  userId: string,
  amount: number,
  description: string,
  actorId: string,
  relatedAuctionId?: string,
): Promise<void> {
  if (amount <= 0) throw new Error('Debit amount must be positive')

  await db.transaction('rw', db.wallets, db.walletTransactions, async () => {
    const wallet = await db.wallets.where('userId').equals(userId).first()
    if (!wallet) throw new Error('Wallet not found')
    const available = wallet.balance - wallet.reservedAmount
    if (available < amount) throw new Error('Insufficient wallet balance')
    await db.wallets.update(wallet.id, {
      balance: wallet.balance - amount,
      updatedAt: Date.now(),
    })
    await recordTransaction(
      wallet.id,
      userId,
      'Debit',
      amount,
      description,
      actorId,
      relatedAuctionId,
    )
  })
}

/**
 * Reserve an amount in the wallet (hold without deducting from balance).
 * Replaces any existing reservation for the same auction so re-bidding works correctly.
 */
export async function reserveForAuction(
  userId: string,
  auctionId: string,
  newReserveAmount: number,
  previousReserveAmount: number,
): Promise<void> {
  await db.transaction('rw', db.wallets, db.walletTransactions, async () => {
    const wallet = await db.wallets.where('userId').equals(userId).first()
    if (!wallet) throw new Error('Wallet not found')

    const delta = newReserveAmount - previousReserveAmount
    const available = wallet.balance - wallet.reservedAmount
    if (delta > 0 && available < delta)
      throw new Error('Insufficient wallet balance for deposit hold')

    await db.wallets.update(wallet.id, {
      reservedAmount: wallet.reservedAmount + delta,
      updatedAt: Date.now(),
    })
    if (delta !== 0) {
      const type: WalletTransactionType = delta > 0 ? 'Reserve' : 'Release'
      await recordTransaction(
        wallet.id,
        userId,
        type,
        Math.abs(delta),
        `Deposit hold adjusted for auction ${auctionId}`,
        userId,
        auctionId,
      )
    }
  })
}

/** Release the reserved hold when an auction ends without the user winning. */
export async function releaseReservation(
  userId: string,
  auctionId: string,
  reservedAmount: number,
): Promise<void> {
  if (reservedAmount <= 0) return

  await db.transaction('rw', db.wallets, db.walletTransactions, async () => {
    const wallet = await db.wallets.where('userId').equals(userId).first()
    if (!wallet) return
    await db.wallets.update(wallet.id, {
      reservedAmount: Math.max(0, wallet.reservedAmount - reservedAmount),
      updatedAt: Date.now(),
    })
    await recordTransaction(
      wallet.id,
      userId,
      'Release',
      reservedAmount,
      `Reservation released — auction ${auctionId}`,
      userId,
      auctionId,
    )
  })
}

/**
 * Deduct the auction deposit from the winner's wallet on award.
 * Converts the existing reservation into an actual deduction.
 */
export async function deductDeposit(
  userId: string,
  auctionId: string,
  depositAmount: number,
): Promise<void> {
  await db.transaction('rw', db.wallets, db.walletTransactions, async () => {
    const wallet = await db.wallets.where('userId').equals(userId).first()
    if (!wallet) throw new Error('Wallet not found')
    await db.wallets.update(wallet.id, {
      balance: wallet.balance - depositAmount,
      reservedAmount: Math.max(0, wallet.reservedAmount - depositAmount),
      updatedAt: Date.now(),
    })
    await recordTransaction(
      wallet.id,
      userId,
      'DepositDeducted',
      depositAmount,
      `Auction deposit deducted — won auction ${auctionId}`,
      userId,
      auctionId,
    )
  })
}

/**
 * DocumentService — CRUD, checkout/checkin, approval workflow, and destruction.
 *
 * Key design decisions (CLAUDE.md #5, #6, #7):
 *   - Exclusive checkout: only one user can edit at a time
 *   - Document number assigned ONLY on Draft → Approved (to avoid numbering gaps)
 *   - Two-step destruction: Reviewer approves → Administrator confirms
 */

import { db } from '@/db'
import { generateId } from '@/crypto'
import { writeAuditLog } from '@/utils/audit'
import { moderateContent } from '@/utils/moderation'
import { requirePermission } from '@/utils/permissions'
import { createNotification, createNotificationForMany } from './notificationService'
import { Role } from '@/types'
import type { Document } from '@/types'

// ── Watermark ─────────────────────────────────────────────────────────────────

export function generateWatermark(userId: string, displayName: string): string {
  const date = new Date().toLocaleDateString('en-CA') // YYYY-MM-DD
  return `CONFIDENTIAL – INTERNAL USE · ${displayName} (${userId.slice(-4)}) · ${date}`
}

// ── Document numbering ────────────────────────────────────────────────────────

async function assignDocumentNumber(): Promise<string> {
  return db.transaction('rw', db.systemConfig, async () => {
    let config = await db.systemConfig.get('singleton')
    if (!config) {
      config = {
        id: 'singleton',
        orgName: 'Meridian',
        documentNumberPrefix: 'ORG',
        documentNumberCounter: 0,
        defaultRetentionYears: 7,
        antiSnipingWindowSeconds: 30,
        antiSnipingExtensionMinutes: 2,
        defaultMinimumIncrement: 100,
        updatedAt: Date.now(),
        updatedBy: 'system',
      }
      await db.systemConfig.add(config)
    }
    const next = config.documentNumberCounter + 1
    await db.systemConfig.update('singleton', {
      documentNumberCounter: next,
      updatedAt: Date.now(),
    })
    const year = new Date().getFullYear()
    return `${config.documentNumberPrefix}-${String(year)}-${String(next).padStart(6, '0')}`
  })
}

// ── CRUD ─────────────────────────────────────────────────────────────────────

export interface DocumentInput {
  title: string
  type: string
  categoryId: string
  body: string
  attachmentUrls: string[]
  retentionYears: number
}

export async function createDocument(
  input: DocumentInput,
  actorId: string,
  actorName: string,
): Promise<Document> {
  requirePermission('createDocument')
  const moderationFlags = await moderateContent([input.title, input.body])
  const doc: Document = {
    id: generateId(),
    ...input,
    status: 'Draft',
    moderationFlags,
    createdBy: actorId,
    createdAt: Date.now(),

import Dexie, { type Table } from 'dexie'
import type { User, Session } from '@/types/auth'
import type { AuditLog } from '@/types/audit'
import type { Auction, Bid, ProxyBid, Wallet, WalletTransaction } from '@/types/auction'
import type { CatalogItem, Category, Tag } from '@/types/catalog'
import type { Publication, PublicationVersion, ViewEvent } from '@/types/publication'
import type {
  Document,
  DocumentVersion,
  CheckoutRecord,
  RetentionPolicy,
  DestructionApproval,
} from '@/types/document'
import type {
  Notification,
  OutboundQueueItem,
  NotificationTemplate,
  NotificationSubscription,
  MessageReadReceipt,
} from '@/types/notification'
import type { TrainingCourse, TrainingProgress } from '@/types/training'
import type { SystemConfig, SensitiveWord } from '@/types/system'

/**
 * MeridianDB — single Dexie database for the entire portal.
 *
 * Schema versioning strategy:
 *   - Version 1 declares ALL tables up front to avoid incremental migrations
 *     during early development (adding a new table requires a version bump in Dexie).
 *   - Future breaking changes (renaming/removing indexes, data migrations) go in
 *     version 2+ with an `upgrade()` function.
 *   - Indexes listed here are for querying only; all fields are stored regardless.
 *   - Dexie index syntax: `&field` = unique, `[a+b]` = compound, `*field` = multi-entry.
 */
export class MeridianDB extends Dexie {
  // ── Auth ───────────────────────────────────────────────────────────────────
  users!: Table<User>
  sessions!: Table<Session>

  // ── Audit (append-only) ────────────────────────────────────────────────────
  auditLogs!: Table<AuditLog>

  // ── Auction ────────────────────────────────────────────────────────────────
  auctions!: Table<Auction>
  bids!: Table<Bid>
  proxyBids!: Table<ProxyBid>
  wallets!: Table<Wallet>
  walletTransactions!: Table<WalletTransaction>

  // ── Catalog ────────────────────────────────────────────────────────────────
  catalogItems!: Table<CatalogItem>
  categories!: Table<Category>
  tags!: Table<Tag>

  // ── Publishing ─────────────────────────────────────────────────────────────
  publications!: Table<Publication>
  publicationVersions!: Table<PublicationVersion>
  viewEvents!: Table<ViewEvent>

  // ── Documents ──────────────────────────────────────────────────────────────
  documents!: Table<Document>
  documentVersions!: Table<DocumentVersion>
  checkoutRecords!: Table<CheckoutRecord>
  retentionPolicies!: Table<RetentionPolicy>
  destructionApprovals!: Table<DestructionApproval>

  // ── Notifications ──────────────────────────────────────────────────────────
  notifications!: Table<Notification>
  outboundQueue!: Table<OutboundQueueItem>
  notificationTemplates!: Table<NotificationTemplate>
  notificationSubscriptions!: Table<NotificationSubscription>
  messageReadReceipts!: Table<MessageReadReceipt>

  // ── Training ───────────────────────────────────────────────────────────────
  trainingCourses!: Table<TrainingCourse>
  trainingProgress!: Table<TrainingProgress>

  // ── System ─────────────────────────────────────────────────────────────────
  systemConfig!: Table<SystemConfig>
  sensitiveWords!: Table<SensitiveWord>

  constructor() {
    super('MeridianPortal')

    this.version(1).stores({
      // ── Auth ──────────────────────────────────────────────────────────────
      // &username = unique index to prevent duplicate usernames
      users: 'id, &username, role, isActive, createdAt',
      sessions: 'id, userId, expiresAt',

      // ── Audit ─────────────────────────────────────────────────────────────
      // Indexed by actor, entity, and type for the audit log viewer filters
      auditLogs: 'id, eventType, actorId, entityType, entityId, createdAt',

      // ── Auction ───────────────────────────────────────────────────────────
      auctions: 'id, status, categoryId, createdBy, startTime, endTime, createdAt',
      // [auctionId+bidderId] compound + idempotencyKey unique prevent duplicate bids
      bids: 'id, auctionId, bidderId, &idempotencyKey, createdAt',
      proxyBids: 'id, auctionId, bidderId, isActive',
      wallets: 'id, &userId',
      walletTransactions: 'id, walletId, userId, type, relatedAuctionId, createdAt',

      // ── Catalog ───────────────────────────────────────────────────────────
      // *tags = multi-entry index so each tag value is indexed individually
      catalogItems: 'id, status, categoryId, *tags, createdBy, createdAt',
      categories: 'id, parentId',
      tags: 'id, &name',

      // ── Publishing ────────────────────────────────────────────────────────
      publications: 'id, type, status, createdBy, createdAt, publishedAt',
      publicationVersions: 'id, publicationId, versionNumber, createdAt',
      // [entityType+entityId] compound for per-entity analytics queries
      viewEvents: 'id, [entityType+entityId], userId, openedAt',

      // ── Documents ─────────────────────────────────────────────────────────
      // &documentNumber unique (sparse — undefined until approved)
      documents:
        'id, documentNumber, status, categoryId, checkedOutBy, retentionDueDate, createdBy, createdAt',
      documentVersions: 'id, documentId, versionNumber, createdAt',
      checkoutRecords: 'id, documentId, userId, isActive, checkedOutAt',
      retentionPolicies: 'id, &categoryId',
      destructionApprovals: 'id, documentId, status, requestedBy, requestedAt',

      // ── Notifications ─────────────────────────────────────────────────────
      notifications: 'id, userId, type, isRead, createdAt',
      outboundQueue: 'id, recipientUserId, status, channel, queuedAt',

      // ── System ────────────────────────────────────────────────────────────
      systemConfig: 'id',
      sensitiveWords: 'id, &word, createdAt',
    })

    // Version 2: outbound retry fields + Message Center + Training tables
    this.version(2).stores({
      // Add nextRetryAt index for efficient retry polling
      outboundQueue: 'id, recipientUserId, status, channel, queuedAt, nextRetryAt',
      // New Message Center tables
      notificationTemplates: 'id, &key, isActive, createdAt',
      notificationSubscriptions: 'id, userId, notificationType',
      messageReadReceipts: 'id, notificationId, userId, readAt',
      // Training module
      trainingCourses: 'id, isActive, createdAt',
      trainingProgress: 'id, userId, courseId, status, updatedAt',
    })
  }
}

