  userId: string,
  auctionId: string,
  newReserveAmount: number,
  previousReserveAmount: number,
): Promise<PreparedReservation> {
  const wallet = await db.wallets.where('userId').equals(userId).first()
  if (!wallet) throw new Error('Wallet not found')
